package com.company.crm.auth;
import com.company.crm.common.ApiResponse;import com.company.crm.security.JwtService;import com.company.crm.security.TenantContext;import com.company.crm.user.*;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.beans.factory.ObjectProvider;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.mail.SimpleMailMessage;import org.springframework.mail.javamail.JavaMailSender;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController {
 private final UserRepository users;private final PasswordEncoder enc;private final JwtService jwt;private final JdbcTemplate db;private final ObjectProvider<JavaMailSender> mail;private final String mailHost,resetUrl;private final long refreshDays,resetMinutes;
 public AuthController(UserRepository u,PasswordEncoder e,JwtService j,JdbcTemplate d,ObjectProvider<JavaMailSender> m,@Value("${spring.mail.host:}")String host,@Value("${crm.password-reset.frontend-url:}")String url,@Value("${crm.refresh-token-days:30}")long days,@Value("${crm.password-reset.token-minutes:30}")long mins){users=u;enc=e;jwt=j;db=d;mail=m;mailHost=host;resetUrl=url;refreshDays=days;resetMinutes=mins;}
 public record LoginRequest(@Email @NotBlank String email,@NotBlank String password){}public record Workspace(UUID id,String name,String slug,String role){}public record Profile(UUID id,String fullName,String email,String role,UUID activeTenantId,List<Workspace> workspaces){}public record TokenData(String accessToken,String refreshToken,String tokenType,long expiresInSeconds,Profile user){}
 public record RefreshRequest(@NotBlank String refreshToken){}public record PasswordRequest(@NotBlank String currentPassword,@NotBlank @Size(min=12)String newPassword){}public record ForgotRequest(@Email @NotBlank String email){}public record ResetRequest(@NotBlank String token,@NotBlank @Size(min=12)String newPassword){}
 private Profile profile(User u){List<Workspace> workspaces=db.query("select t.id,t.name,t.slug,m.role from tenant_memberships m join tenants t on t.id=m.tenant_id where m.user_id=? and m.membership_status='ACTIVE' and t.status='ACTIVE' order by t.created_at,t.id",(rs,n)->new Workspace(rs.getObject("id",UUID.class),rs.getString("name"),rs.getString("slug"),rs.getString("role")),u.getId());UUID activeId=TenantContext.currentTenantId();Workspace active=activeId==null?null:workspaces.stream().filter(w->w.id().equals(activeId)).findFirst().orElse(null);if(active==null)active=workspaces.isEmpty()?null:workspaces.get(0);return new Profile(u.getId(),u.getFullName(),u.getEmail(),active==null?u.getRole().name():active.role(),active==null?null:active.id(),workspaces);}
 private String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private String randomToken(){byte[] b=new byte[48];new SecureRandom().nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}
 private String saveRefresh(User u){String raw=randomToken();db.update("insert into refresh_tokens(id,user_id,token_hash,expires_at) values(?,?,?,?)",UUID.randomUUID(),u.getId(),hash(raw),java.sql.Timestamp.from(Instant.now().plusSeconds(refreshDays*86400)));return raw;}
 @PostMapping("/login")public ApiResponse<TokenData> login(@Valid @RequestBody LoginRequest r){User u=users.findByEmailIgnoreCase(r.email()).filter(User::isActive).filter(User::isEmailVerified).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials"));if(!enc.matches(r.password(),u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials");return ApiResponse.ok("Login successful",new TokenData(jwt.issue(u),saveRefresh(u),"Bearer",jwt.expiresSeconds(),profile(u)));}
 @PostMapping("/refresh")@Transactional public ApiResponse<TokenData> refresh(@Valid @RequestBody RefreshRequest r){String h=hash(r.refreshToken());var rows=db.queryForList("select user_id from refresh_tokens where token_hash=? and revoked_at is null and expires_at>now()",h);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Refresh token invalid or expired");UUID id=(UUID)rows.get(0).get("user_id");User u=users.findById(id).filter(User::isActive).filter(User::isEmailVerified).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Account unavailable"));db.update("update refresh_tokens set revoked_at=now() where token_hash=?",h);return ApiResponse.ok("Token rotated",new TokenData(jwt.issue(u),saveRefresh(u),"Bearer",jwt.expiresSeconds(),profile(u)));}
 @PostMapping("/logout")public ResponseEntity<Void> logout(@RequestBody(required=false)RefreshRequest r){if(r!=null&&r.refreshToken()!=null)db.update("update refresh_tokens set revoked_at=now() where token_hash=? and revoked_at is null",hash(r.refreshToken()));return ResponseEntity.noContent().build();}
 @GetMapping("/me")public ApiResponse<Profile> me(org.springframework.security.core.Authentication a){return ApiResponse.ok("Current user",profile(users.findByEmailIgnoreCase(a.getName()).orElseThrow()));}
 @PostMapping("/change-password")@Transactional public ResponseEntity<Void> changePassword(@Valid @RequestBody PasswordRequest r,org.springframework.security.core.Authentication a){User u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();if(!enc.matches(r.currentPassword(),u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Current password is incorrect");db.update("update users set password_hash=? where id=?",enc.encode(r.newPassword()),u.getId());db.update("update refresh_tokens set revoked_at=now() where user_id=? and revoked_at is null",u.getId());return ResponseEntity.noContent().build();}
 @PostMapping("/forgot-password")@Transactional public ResponseEntity<Void> forgot(@Valid @RequestBody ForgotRequest r){if(mailHost.isBlank()||resetUrl.isBlank())return ResponseEntity.accepted().build();users.findByEmailIgnoreCase(r.email()).filter(User::isActive).ifPresent(u->{String raw=randomToken();db.update("insert into password_reset_tokens(id,user_id,token_hash,expires_at) values(?,?,?,?)",UUID.randomUUID(),u.getId(),hash(raw),java.sql.Timestamp.from(Instant.now().plusSeconds(resetMinutes*60)));SimpleMailMessage msg=new SimpleMailMessage();msg.setTo(u.getEmail());msg.setSubject("CRM password reset");msg.setText("Use this one-time link to reset your password: "+resetUrl+"#token="+raw+" . The link expires in "+resetMinutes+" minutes.");mail.getObject().send(msg);});return ResponseEntity.accepted().build();}
 @PostMapping("/reset-password")@Transactional public ResponseEntity<Void> reset(@Valid @RequestBody ResetRequest r){String h=hash(r.token());var rows=db.queryForList("select user_id from password_reset_tokens where token_hash=? and used_at is null and expires_at>now()",h);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Reset token invalid or expired");UUID id=(UUID)rows.get(0).get("user_id");db.update("update users set password_hash=? where id=?",enc.encode(r.newPassword()),id);db.update("update password_reset_tokens set used_at=now() where token_hash=?",h);db.update("update refresh_tokens set revoked_at=now() where user_id=? and revoked_at is null",id);return ResponseEntity.noContent().build();}
}


